mapper.select:
SELECT EXISTS (
    SELECT 1 FROM sys_user
    WHERE is_super_admin = 1 AND deleted_at = 0
) AND NOT EXISTS (
    SELECT 1 FROM sys_user
    WHERE id = #{operatorId}
      AND is_super_admin = 1
      AND status = 1
      AND deleted_at = 0
)

mapper.insert:
INSERT INTO sys_menu (
    parent_id, menu_type, menu_code, menu_name, route_path, component,
    icon, permission_code, visible, cacheable, external_link, sort_order,
    status, remark, created_by, updated_by
) VALUES (
    #{parentId}, #{menuType}, #{menuCode}, #{menuName}, #{routePath}, #{component},
    #{icon}, #{permissionCode}, #{visible}, #{cacheable}, #{externalLink}, #{sortOrder},
    #{status}, #{remark}, #{createdBy}, #{updatedBy}
)

mapper.update:
UPDATE sys_menu
SET status = 0, deleted_at = #{deletedAt}, updated_by = #{updatedBy}
WHERE id = #{id} AND deleted_at = 0

UPDATE sys_role_menu
SET deleted_at = #{deletedAt}
WHERE menu_id = #{menuId} AND deleted_at = 0
